	[8091] = {
		Title = "Relatório de teste",
		Page = {
			[1] = {
				[1] = "O objetivo da Fase 1 é observar o progresso após o implante do núcleo e confirmar a sobrevivência da cobaia. Como a potência do Battle Core foi aumentada, será necessário realizar ajustes detalhados de acordo com cada cobaia no momento do implante.",
				[2] = "",
				[3] = "Após alcançar a sobrevivência pelo tempo estipulado, prosseguir imediatamente para a Fase 2."
			}
		}
	},
	[8092] = {
		Title = "Relatório de teste",
		Page = {
			[1] = {
				[1] = "O objetivo do experimento da Fase 2 é levar o potencial de combate do organismo vivo ao limite, observar o progresso e obter dados significativos.",
				[2] = "",
				[3] = "Para o experimento da Fase 2, fornecer um ambiente estimulante no qual a cobaia possa extrair e liberar o poder do Battle Core, medindo seus limites.",
				[4] = "",
				[5] = "Como cada classe requer um ambiente diferente, verificar o perfil da cobaia e conduzir o experimento separadamente em cada laboratório. Após o término do experimento, solicita-se o envio do relatório o mais rápido possível.",
				[6] = "",
				[7] = "Diretor de Pesquisa Wolfchev"
			}
		}
	},
	[8093] = {
		Title = "Relatório de teste",
		Page = {
			[1] = {
				[1] = "Mesmo quando o implante é bem-sucedido, foram observadas cobaias que apresentam dificuldade em utilizar o poder do Battle Core.",
				[2] = "",
				[3] = "Foi confirmado que cobaias que apresentam a reação de sangue negro (nota: fenômeno de vomitar sangue negro. Em casos graves, sangue negro também flui pelos olhos, ouvidos e ferimentos antigos ou recém-formados) não podem ser recuperadas.",
				[4] = "",
				[5] = "Após a reação de sangue negro ocorrer, a morte acontece no mínimo imediatamente e, no máximo, dentro de 5 horas. No entanto, foi descoberto um fenômeno incomum após a morte, denominado 'transformação em entidade de pensamento'…"
			}
		}
	},
	[8094] = {
		Title = "Relatório de teste",
		Page = {
			[1] = {
				[1] = "A entidade de pensamento surge dentro de até 2 dias após a morte. A primeira entidade de pensamento possui uma consciência relativamente clara, mas apresenta a característica de possuir apenas um único objetivo de forma cega.",
				[2] = "",
				[3] = "Levantamos a hipótese de que esse objetivo esteja relacionado a situações intensamente estimulantes vivenciadas antes da morte, porém são necessários experimentos adicionais.",
				[4] = "",
				[5] = "No caso da primeira entidade de pensamento, também foram encontrados casos em que ela se assemelha muito à aparência de quando estava viva, dificultando sua distinção, ocorrendo de forma ainda mais evidente quando a consciência de propósito da cobaia é forte."
			}
		}
	},
	[8095] = {
		Title = "Relatório de teste",
		Page = {
			[1] = {
				[1] = "No caso da cobaia Espadachim Egnigem, denominada 'fracasso' pelo Diretor de Pesquisa Dr. Wolfchev, conforme a transformação em entidade de pensamento progride, seu senso original de propósito foi alterado para apenas um desejo de massacre.",
				[2] = "",
				[3] = "No entanto, ao aplicar certa forma de lavagem cerebral, observou-se um fenômeno em que o desejo de massacre pode ser direcionado a um alvo específico. Para a medição detalhada desse fenômeno, o próprio Dr. Wolfchev realiza a supervisão direta."
			}
		}
	},
	[8096] = {
		Title = "Relatório de teste",
		Page = {
			[1] = {
				[1] = "Exceto em casos especiais, conforme a transformação em entidade de pensamento progride e se divide em maior número, o objetivo inicial é perdido e parece que passam a se apegar apenas ao assassinato e à destruição.",
				[2] = "",
				[3] = "Como existem poucos métodos para retomar o controle de entidades de pensamento que escaparam do controle, é necessária observação cuidadosa e isolamento durante a progressão da transformação em entidade de pensamento."
			}
		}
	},
	[8097] = {
		Title = "Relatório de teste",
		Page = {
			[1] = {
				[1] = "O coração de Ymir modificado, isto é, o Battle Core, pode ser implantado em humanos para torná-los entidades mais fortes do que são agora? A resposta para essa pergunta nem precisa ser feita. É possível.",
				[2] = "",
				[3] = "No entanto, falta apenas uma coisa. Uma vontade ainda maior de viver. Uma vontade forte o suficiente para não se deixar consumir pela Fúria e se autodestruir! Precisamos de indivíduos com uma força mental ainda maior!"
			}
		}
	},
	[8098] = {
		Title = "Relatório de teste",
		Page = {
			[1] = {
				[1] = "Uma expedição não oficial que partiu secretamente do Reino de Rune-Midgarts. Aventureiros de elite que não deixariam registros mesmo que não retornassem vivos.",
				[2] = "",
				[3] = "Não seriam essas as cobaias perfeitas preparadas para mim!",
				[4] = "",
				[5] = "Exigi um pouco demais, mas com o poder de Rekenber, unindo forças com uma certa figura de Rune-Midgarts, foi possível desviá-los sem que nem mesmo o presidente soubesse.",
				[6] = "",
				[7] = "Agora, o palco para minhas adoráveis crianças está perfeito. Tudo o que resta é oferecer a elas o máximo respeito pelo desfecho que alcançarão através do melhor experimento."
			}
		}
	},
	[8099] = {
		Title = "Relatório de teste",
		Page = {
			[1] = {
				[1] = "Ah... estou morrendo de sono. Que diabos é isso, quantos dias já são? Quero ir para casa. Ultimamente, quando finalmente volto para casa depois de tanto tempo, meu gato nem reconhece meu rosto e fica bufando para mim.",
				[2] = "",
				[3] = "Dizendo que quer implementar uma vida com tempo para o jantar, mas fica coletando registros biológicos e ainda troca equipamentos perfeitamente bons por porcarias... sinceramente, tanto faz empresa ou qualquer coisa, tomara que tudo vá à falência…… o quê é isso, isso não é meu diário, espera por que isso não apaga &#%&@…",
				[4] = "",
				[5] = "^FF0000Este pesquisador foi descartado. O texto original é preservado para registro do motivo do descarte.^000000"
			}
		}
	},
	[8100] = {
		Title = "Relatório de teste",
		Page = {
			[1] = {
				[1] = "O objetivo da Fase 1 é substituir o coração pelo protótipo do núcleo e observar o progresso; após alcançar a sobrevivência durante o tempo estipulado, prosseguir imediatamente para a Fase 2.",
				[2] = "",
				[3] = "O objetivo do experimento da Fase 2 é maximizar o potencial de combate do organismo vivo, observar o progresso e obter dados significativos.",
				[4] = "",
				[5] = "Para o experimento da Fase 2, fornecer um ambiente estimulante no qual a cobaia possa extrair e liberar o poder do Battle Core, medindo seus limites…",
				[6] = "",
				[7] = "É necessário ter extremo cuidado para que estímulos excessivos não levem à morte, porém atualmente a taxa de mortalidade é de 100%, como alternativa, a vontade das entidades de pensamento…"
			}
		}
	},
