	[9162] = {
		Title = "Introdução ao Projeto de Modificação de Equipamentos do Instituto de Pesquisa Regenshrium#Item Reform",
		Page = {
			[1] = {
				[1] = "Os quatro times afiliados ao Instituto de Pesquisa Regenshrium, subordinado à Lakenver, estão aprimorando sua qualidade por meio de experimentos realizados de maneiras diferentes, visando alcançar a comercialização.",
				[2] = "Eles recebem solicitações de aventureiros apenas para equipamentos cujas pesquisas tenham sido concluídas com sucesso, e então os modificam, atualizando-os para novos equipamentos.",
				[3] = "Todo o processo tem como objetivo acumular dados; por isso, os resultados são devolvidos ao proprietário.",
				[4] = "Que sorte, não é mesmo?",
				[5] = "",
				[6] = "Observe, por favor, que para realizar a modificação, normalmente é necessário possuir pelo menos um nível mínimo de refino.",
				[7] = "",
				[8] = "Consulte as listas de cada equipamento para ver quais itens são tratados.",
				[9] = "",
				[10] = "<TIPBOX>•[Team Artnad]<INFO>9163</INFO></TIPBOX>",
				[11] = "Time de Pesquisa Especializado em Armas",
				[12] = "",
